await (async(page)=>{await page.getByText('5. 普通光谱后处理',{exact:true}).first().click();await page.getByRole('tab',{name:'平滑 Smoothing',exact:true}).click();await page.getByRole('button',{name:'计算当前平滑预览',exact:true}).click();await page.getByText(/当前预览 · S ·/).waitFor();await page.getByRole('button',{name:'确认当前平滑',exact:true}).click();await page.getByText('S · 平滑校正谱：已确认',{exact:true}).waitFor();const newS=await page.getByText(/已确认结果 · S ·/).innerText();await page.getByRole('tab',{name:'归一化 Normalization',exact:true}).click();const staleText=await page.getByText(/^N_S · 平滑后归一化：/).innerText();await page.getByRole('button',{name:'使用未平滑校正谱 B',exact:true}).click();await page.getByText('当前归一化来源：B · 最终基线校正谱',{exact:true}).waitFor();const nb=await page.getByText(/^N_B · 基线后归一化：/).innerText();await page.getByRole('tab',{name:'结果导出',exact:true}).click();const exportChoiceBefore=await page.getByRole('combobox',{name:'后处理导出分支',exact:true}).inputValue();await page.getByRole('combobox',{name:'后处理导出分支',exact:true}).focus();await page.getByRole('combobox',{name:'后处理导出分支',exact:true}).press('ArrowDown');await page.getByRole('option',{name:'N_S · 平滑后归一化',exact:true}).click();await page.getByText(/已选择全部分支/).waitFor({state:'hidden'});await page.getByRole('combobox',{name:'后处理导出范围',exact:true}).focus();await page.getByRole('combobox',{name:'后处理导出范围',exact:true}).press('ArrowDown');await page.getByRole('option',{name:'全部条目',exact:true}).click();return{newS,staleText,nb,exportChoiceBefore,strictDisabled:await page.getByRole('button',{name:'打包已确认后处理结果',exact:true}).isDisabled()};})(page);
